@@ -36,5 +42,59 @@
 //
 // Anything else: undefined.
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = basename(argv[0]);
+
+  if (cmd === 'git') {
+    let i = 1;
+    while (i < argv.length && argv[i].startsWith('-')) {
+      i += ['-C', '-c', '--git-dir', '--work-tree', '--namespace'].includes(argv[i]) ? 2 : 1;
+    }
+    const sub = argv[i];
+    const args = argv.slice(i + 1);
+    if (sub === 'push') {
+      const forced = args.some(
+        (w) =>
+          ['--force', '--force-with-lease', '--mirror', '--delete', '--prune'].includes(w.split('=')[0]) ||
+          (shortGroup(w) && /[fd]/.test(w)) ||
+          (!w.startsWith('-') && /^[+:]/.test(w)),
+      );
+      return forced ? { name: 'force-push', reason: 'git push --force rewrites remote history' } : undefined;
+    }
+    if (sub === 'reset' && args.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+    if (sub === 'clean') {
+      const forced = args.some((w) => w === '--force' || (shortGroup(w) && w.includes('f')));
+      const dry = args.some((w) => w === '-n' || w === '--dry-run');
+      return forced && !dry ? { name: 'clean-force', reason: 'git clean -f deletes untracked files' } : undefined;
+    }
+    return undefined;
+  }
+
+  if (cmd === 'rm') {
+    const rest = argv.slice(1);
+    const dd = rest.indexOf('--');
+    const before = dd < 0 ? rest : rest.slice(0, dd);
+    const after = dd < 0 ? [] : rest.slice(dd + 1);
+    const flags = before.filter((w) => w.startsWith('-'));
+    const targets = [...before.filter((w) => !w.startsWith('-')), ...after];
+    const recursive = flags.some((w) => w === '--recursive' || (shortGroup(w) && /[rR]/.test(w)));
+    if (!recursive) return undefined;
+    if (targets.length === 0) return rmOutside('rm -r with no targets');
+    if (targets.some((t) => outside(t, cwd) || sameDir(t, cwd))) return rmOutside('rm -r outside the working directory');
+    return undefined;
+  }
+
+  if (cmd === 'find') {
+    if (!argv.some((w) => ['-delete', '-exec', '-execdir'].includes(w))) return undefined;
+    const starts: string[] = [];
